function B($o,[string]$key,[bool]$value){if(!$o.PSObject.Properties[$key] -or $o.$key -isnot [bool] -or [bool]$o.$key -ne $value){throw "Missing/wrong Boolean: $key"}}
function Close([double]$a,[double]$b){[Math]::Abs($a-$b) -le 64*2.2204460492503131e-16*[Math]::Max(1.,[Math]::Max([Math]::Abs($a),[Math]::Abs($b)))}
