$cpuCheckPath=Join-Path $logs 'upl_gravity_wall_cpu_DebugCPU_constant_smoke_r1_reader.check.json';$cpuCheck=J $cpuCheckPath;$cpuDone=J $cpuCheck.completion.path;$cpuReview=Split-Path -Parent $cpuCheck.completion.path
if(!$cpuCheck.passed -or !$cpuCheck.pure_reader_only -or $cpuCheck.source_run_or_old_control.sha256 -ine (E $cpuRunPath).sha256 -or !$cpuDone.passed -or $cpuDone.stage -cne 'upl_gravity_wall_cpu_r1' -or $cpuDone.model -cne 'constant' -or $cpuDone.window -cne 'smoke' -or $cpuDone.backend -cne 'CPU_private_tangential_gravity' -or $cpuDone.samples -ne 3 -or $cpuDone.native_count -ne 1024 -or $cpuDone.fixed_count -ne 256 -or $cpuDone.common_columns -ne 33 -or $cpuDone.native_J_arrays -ne 3 -or !$cpuDone.V_rho_k_derived_not_native -or $cpuDone.public_dynamic_metadata -or $cpuDone.physical_acceptance){throw 'Existing private3J CPU smoke reader required; public6J is not a substitute'}
