function Owned($e,[bool]$mem){V @($e);$q=J $e.path;V @($q.program,$q.log);if($q.target_program){V @($q.target_program)};if(!$q.owned_call_exited -or !$q.typed_LASTEXITCODE_captured_immediately -or $q.exit_code -ne 0 -or $q.invocation_failure -or $q.launch_error -or ($mem -and !$q.memcheck_zero_errors_and_leaks)){throw 'Owned exit/memcheck failed; retain partials and do not rerun completed program'};$q}
