function Call([string[]]$argv,[string]$label,[bool]$mem,[string]$role){
 $p=Join-Path $logs ($label+'.call.json');$log=Join-Path $logs ($label+'.log');Fresh @($p,$log);$program=$h.program;$arguments=$argv;$toolSource=$null
 if($mem){$toolSource=E (Join-Path $logs 'upl_gpu_wall_component_Debug_r2.call.json');$old=J $toolSource.path;V @($old.program,$old.log);if(!$old.owned_call_exited -or $old.exit_code -ne 0 -or !$old.memcheck_zero_errors_and_leaks){throw 'Successful historical memcheck tool provenance required'};if([IO.Path]::GetFileName($old.program.path) -ine 'compute-sanitizer.exe'){throw 'Existing actual Debug memcheck tool required'};$program=$old.program;$arguments=@('--tool','memcheck','--leak-check','full','--error-exitcode','97',$h.program.path)+$argv}
 V @($program,$h.program);[IO.File]::WriteAllBytes($log,[byte[]]@());$start=[DateTime]::UtcNow.ToString('o');$code=$null;$failure=$null;$preference=$ErrorActionPreference;$ErrorActionPreference='Continue'
