  foreach($leaf in 'physical.bin','frame.bin'){if((Get-Item -LiteralPath (Join-Path $dir $leaf)).Length -ne 811044){throw 'Three complete 33-column frames required'}}
  if((N $d.max_energy_ratio) -gt 1.1 -or (N $d.max_abs_J_minus_1) -gt 1e-4 -or (N $d.max_abs_J_minus_1) -le $(if($window -ceq 'smoke'){0.}else{1e-8}) -or (N $d.max_saved_coupled_CFL) -gt .01 -or (N $d.max_saved_Ddt_h2) -gt .01 -or (N $d.max_ledger_relative_error) -gt 5e-13 -or (N $d.max_signed_dterror_s) -gt 1e-14 -or (N $d.min_signed_dterror_s) -gt (N $d.max_signed_dterror_s) -or $d.conductivity_model -ne $(if($model -ceq 'variable'){1}else{0}) -or (N $d.conductivity_Ck) -ne $(if($model -ceq 'variable'){.0001220703125}else{0.}) -or (N $d.conductivity_m_s) -ne $(if($model -ceq 'k0'){0.}else{[double]([single]0.0001)}) -or ($model -ceq 'variable' -and $window -ceq 'full' -and (N $d.max_k_span_over_k0) -lt .005)){throw 'Original native safety/ledger/energy/law gates failed'}
