  for($i=0;$i -lt 1024*33*8;$i++){if($frames[0][$i] -ne $frames[1][$i]){throw ('Initial soil33 bit mismatch at row'+[int][Math]::Floor($i/(33*8))+' column'+[int][Math]::Floor(($i%(33*8))/8))}}
